        "2": {
          "trigger": {
            "custom": "function(event, _, _, spell_id) -- Source is always player\n    local now = GetTime()\n    \n    if event == \"UNIT_SPELLCAST_START\" then\n        aura_env.last_cast_started = spell_id\n        aura_env.last_cast_started_at = now\n    else\n        local start, duration = GetSpellCooldown(61304)\n        if duration == 0 then\n            return false\n        end\n        \n        if aura_env.last_cast_started ~= spell_id then\n            local name, _, icon = GetSpellInfo(spell_id)\n            aura_env.name = name\n            aura_env.icon = icon\n            return true\n        end\n        \n        -- Casts faster than the GCD\n        aura_env.name = name\n        aura_env.icon = icon\n        return true\n    end\nend",
            "customDuration": "function()\n    local start, duration = GetSpellCooldown(61304)\n    return duration, duration + start\nend\n\n\n",
            "customIcon": "function()\n    return aura_env.icon\nend\n\n\n",
            "customName": "function()\n    return aura_env.name \nend",
