            "check": "event",
            "custom": "function(allstates, event, player, subEvent, srcGUID, _,_,destGUID,_,_, ...)\n    local currentTime = GetTime()\n    local ae = aura_env\n    if event == \"UNIT_SPELLCAST_START\" and player == \"player\" and subEvent == ae.slam then\n        -- pause swing timer\n        if ae.plannedSwingMain > currentTime then\n            ae.casting = true\n            ae.mainTimeLeft = ae.plannedSwingMain - currentTime\n            allstates[\"main\"] = {\n                show = true,\n                changed = true,\n                icon = ae.icons.main,\n                progressType = \"static\",\n                paused = true,\n                value = ae.mainTimeLeft,\n                total = ae.mainSpeed,\n                speed = \"casting\",\n            }\n            return true\n        end\n    elseif event == \"CURRENT_SPELL_CAST_CHANGED\" and ae.checkQueuedAction then\n        if ae.casting then return end\n        if ae.icons.main ~= ae.icons[47450] and IsCurrentSpell(47450) then\n            ae.icons.main = ae.icons[47450]     \n            allstates[\"main\"][\"icon\"] = ae.icons.main\n            allstates[\"main\"][\"changed\"] = true\n            return true\n        elseif ae.icons.main ~= ae.icons[47520] and IsCurrentSpell(47520) then\n            ae.icons.main = ae.icons[47520]     \n            allstates[\"main\"][\"icon\"] = ae.icons.main\n            allstates[\"main\"][\"changed\"] = true\n            return true\n        elseif ae.icons.main ~= ae.icons[56815] and IsCurrentSpell(56815) then\n            ae.icons.main = ae.icons[56815]     \n            allstates[\"main\"][\"icon\"] = ae.icons.main\n            allstates[\"main\"][\"changed\"] = true\n        elseif ae.icons.main ~= ae.icons[48996] and IsCurrentSpell(48996) then\n            ae.icons.main = ae.icons[48996]     \n            allstates[\"main\"][\"icon\"] = ae.icons.main\n            allstates[\"main\"][\"changed\"] = true\n            return true\n        elseif ae.icons.main ~= ae.icons.mainWeapon then\n            ae.icons.main = ae.icons.mainWeapon\n        end \n        return\n    elseif event == \"PLAYER_EQUIPMENT_CHANGED\" then\n        ae.getWeaponsInfo()\n        \n        ae.plannedSwingMain = currentTime + ae.mainSpeed\n        allstates[\"main\"] = ae.setSwingTimer(\"main\", ae.mainSpeed, ae.plannedSwingMain)\n        if ae.offSpeed ~= 0 then           \n            ae.plannedSwingOff = currentTime + ae.offSpeed\n            allstates[\"off\"] = ae.setSwingTimer(\"off\", ae.offSpeed, ae.plannedSwingOff)\n        else\n            allstates[\"off\"] = nil\n        end\n        return true\n    elseif event == \"UNIT_SPELLCAST_INTERRUPTED\" and player == \"player\" then\n        if ae.casting then\n            ae.casting = false\n            ae.plannedSwingMain = currentTime + ae.mainTimeLeft\n            allstates[\"main\"] = ae.setSwingTimer(\"main\", ae.mainSpeed, ae.plannedSwingMain)\n            if allstates[\"off\"] and ae.offTimeLeft ~= 0 then\n                ae.plannedSwingOff = currentTime + ae.offTimeLeft\n                allstates[\"off\"] = ae.setSwingTimer(\"off\", ae.offSpeed, ae.plannedSwingOff)\n            end\n            return true\n        end\n    elseif event == \"UNIT_SPELLCAST_SUCCEEDED\" then\n        if player == \"player\"  then\n            if ae.casting then\n                ae.casting = false\n                ae.plannedSwingMain = currentTime + ae.mainTimeLeft\n                allstates[\"main\"] = ae.setSwingTimer(\"main\", ae.mainSpeed, ae.plannedSwingMain)\n                if allstates[\"off\"] and ae.offTimeLeft ~= 0 then\n                    ae.plannedSwingOff = currentTime + ae.offTimeLeft\n                    allstates[\"off\"] = ae.setSwingTimer(\"off\", ae.offSpeed, ae.plannedSwingOff)\n                end\n                return true\n            elseif subEvent == ae.ht or subEvent == ae.ws then -- reset swing\n                ae.plannedSwingMain = currentTime + ae.mainSpeed\n                allstates[\"main\"] = ae.setSwingTimer(\"main\", ae.mainSpeed, ae.plannedSwingMain)\n                ae.lastSwing = currentTime\n                return true\n            elseif subEvent == ae.hs or subEvent == ae.cleave or subEvent == ae.rs or subEvent == ae.raptor then\n                ae.icons.main = ae.icons.mainWeapon\n                local mainSpeed, offSpeed = UnitAttackSpeed(\"player\")\n                offSpeed = offSpeed or 0\n                if ae.plannedSwingMain > ae.plannedSwingOff and offSpeed ~= 0 then\n                    ae.plannedSwingOff = ae.plannedSwingMain\n                    allstates[\"off\"] = ae.setSwingTimer(\"off\", offSpeed, ae.plannedSwingOff)\n                end\n                ae.lastSwing = currentTime\n                ae.plannedSwingMain = mainSpeed + currentTime\n                allstates[\"main\"] = ae.setSwingTimer(\"main\", mainSpeed, ae.plannedSwingMain)\n                \n                ae.mainSpeed, ae.offSpeed = mainSpeed, offSpeed\n                return true\n            end\n        end\n        return\n    end\n    \n    if event == \"UNIT_ATTACK_SPEED\" then\n        local newMainSpeed, newOffSpeed = UnitAttackSpeed(\"player\")\n        newOffSpeed = newOffSpeed or 0\n        if ae.casting then\n            ae.mainSpeed, ae.offSpeed = newMainSpeed, newOffSpeed\n            return\n        end\n        \n        if ae.plannedSwingMain > currentTime then\n            if newMainSpeed ~= ae.mainSpeed then               \n                local multiplier = newMainSpeed / ae.mainSpeed \n                local timeLeft = (ae.plannedSwingMain - currentTime) * multiplier\n                ae.plannedSwingMain = currentTime + timeLeft\n                allstates[\"main\"] = ae.setSwingTimer(\"main\", newMainSpeed, ae.plannedSwingMain)\n            end\n        end\n        \n        if ae.offSpeed == 0 and newOffSpeed ~= 0 then\n            ae.plannedSwingOff = currentTime + newOffSpeed\n            allstates[\"off\"] = ae.setSwingTimer(\"off\", newOffSpeed, ae.plannedSwingOff)\n        elseif allstates[\"off\"] and ae.plannedSwingOff > currentTime then\n            if newOffSpeed ~= ae.offSpeed and newOffSpeed ~= 0 then\n                local multiplier = newOffSpeed / ae.offSpeed\n                local timeLeft = (ae.plannedSwingOff - currentTime) * multiplier\n                ae.plannedSwingOff = currentTime + timeLeft\n                allstates[\"off\"] = ae.setSwingTimer(\"off\", newOffSpeed, ae.plannedSwingOff)  \n            end\n        end\n        if allstates[\"main\"] then ae.updateWeaponSpeed(allstates.main, newMainSpeed) end\n        if allstates[\"off\"] then ae.updateWeaponSpeed(allstates.off, newOffSpeed) end\n        ae.mainSpeed, ae.offSpeed = newMainSpeed, newOffSpeed\n        return true\n    end\n    \n    if (destGUID == UnitGUID(\"player\") and ((select(1, ...) == \"PARRY\" or select(4, ...) == \"PARRY\"))) then\n        local timeLeft = ae.plannedSwingMain - currentTime\n        if (timeLeft > (0.6 * ae.mainSpeed)) then\n            ae.plannedSwingMain = ae.plannedSwingMain - 0.4 * ae.mainSpeed\n            allstates[\"main\"] = ae.setSwingTimer(\"main\", ae.mainSpeed, ae.plannedSwingMain)\n            return true\n        elseif (timeLeft > (0.2 * ae.mainSpeed)) then\n            ae.plannedSwingMain = ae.plannedSwingMain - 0.2 * ae.mainSpeed\n            allstates[\"main\"] = ae.setSwingTimer(\"main\", ae.mainSpeed, ae.plannedSwingMain)\n            return true\n        end\n        return\n    elseif UnitGUID(\"player\") ~= srcGUID then return end\n    \n    local mainSpeed, offSpeed = UnitAttackSpeed(\"player\")\n    offSpeed = offSpeed or 0\n    \n    if subEvent == \"SWING_DAMAGE\" or subEvent == \"SWING_MISSED\" then\n        local diffMain = math.abs(currentTime - ae.plannedSwingMain)\n        local diffOff = math.abs(currentTime - ae.plannedSwingOff)\n        if (ae.plannedSwingMain + 0.15 < currentTime) and (ae.plannedSwingOff + 0.15 < currentTime ) then\n            ae.lastSwing = currentTime\n            ae.plannedSwingMain = mainSpeed + currentTime\n            allstates[\"main\"] = ae.setSwingTimer(\"main\", mainSpeed, ae.plannedSwingMain)\n            ae.mainSpeed, ae.offSpeed = mainSpeed, offSpeed\n            if offSpeed ~= 0 and offSpeed ~= mainSpeed then\n                ae.offSet = true\n                ae.plannedSwingOff = currentTime + 0.2\n                allstates[\"off\"] = ae.setSwingTimer(\"off\", offSpeed, ae.plannedSwingOff)\n            end\n            return true\n        elseif (((diffMain <= diffOff) and (diffMain < 0.15)) or (aura_env.plannedSwingMain <= aura_env.plannedSwingOff)) or (offSpeed == 0) then\n            ae.lastSwing = currentTime\n            ae.plannedSwingMain = mainSpeed + currentTime\n            allstates[\"main\"] = ae.setSwingTimer(\"main\", mainSpeed, ae.plannedSwingMain)\n            ae.mainSpeed, ae.offSpeed = mainSpeed, offSpeed\n            return true\n        else\n            ae.lastSwing = currentTime\n            ae.plannedSwingOff = offSpeed + currentTime\n            if ae.offSet then\n                ae.plannedSwingOff = ae.plannedSwingOff - 0.2\n                ae.offSet = false\n            end\n            allstates[\"off\"] = ae.setSwingTimer(\"off\", offSpeed, ae.plannedSwingOff)\n            ae.mainSpeed, ae.offSpeed = mainSpeed, offSpeed\n            return true\n        end\n    end   \nend",
            "customVariables": "{\n    hand = \"string\",\n    speed = \"string\"\n}",
            "custom_hide": "timed",
            "custom_type": "stateupdate",
