      "actions": {
        "finish": [],
        "init": {
          "custom": "local cfg = aura_env.config.options\nlocal color = cfg.tickColor\nlocal width = cfg.tickWidth\n\naura_env.barSubRegions = {}\naura_env.lastCondCheck = 0\n\naura_env.SetTicksCount = function(increment, start)\n    if increment < 0.05 then\n        return\n    end\n    \n    local point = 100 - start\n    \n    if start == 0 then\n        point = point - increment\n    end\n    \n    aura_env.barSubRegions = {}\n    \n    for _, subRegion in ipairs(aura_env.region.subRegions) do\n        if subRegion.type == \"subtick\" then\n            if point >= 0 then\n                subRegion:SetTickPlacement(point)\n                subRegion:SetTickColor(color[1], color[2], color[3], color[4])\n                subRegion.tick_thickness = width\n                subRegion:SetTickLength(width)\n                subRegion:UpdateTickSize()\n                subRegion:SetVisible(true)\n                aura_env.barSubRegions[point] = subRegion\n                point = point - increment\n            else\n                subRegion:SetVisible(false)\n            end\n        end\n    end\nend\n\nlocal GetSpellName = function(id)\n    return select(1, GetSpellInfo(id))\nend\n\naura_env.spellConfig = {}",
          "do_custom": true
        },
