      "triggers": {
        "1": {
          "trigger": {
            "debuffType": "HELPFUL",
            "event": "Cast",
            "names": [],
            "spellIds": [],
            "subeventPrefix": "SPELL",
            "subeventSuffix": "_CAST_START",
            "type": "unit",
            "unit": "player",
            "use_absorbHealMode": true,
            "use_absorbMode": true,
            "use_unit": true
          },
          "untrigger": []
        },
        "2": {
          "trigger": {
            "check": "event",
            "custom": "function(a, e, ...)\n    if e == 'UNIT_SPELLCAST_SENT' then\n        local _, spellName, _, destName, _ = ...\n        if destName and destName == WeakAuras.me or UnitInRaid(destName) or UnitInParty(destName) then\n            aura_env.sentDestName = destName\n            aura_env.sentSpellName = spellName\n        else\n            aura_env.sentDestName = nil\n            aura_env.sentSpellName = nil\n        end\n    end\n    \n    if e == 'UNIT_SPELLCAST_START' then\n        local _, spellName = ...\n        if spellName == aura_env.sentSpellName then\n            aura_env.destName = aura_env.sentDestName\n        else\n            aura_env.destName = nil\n        end\n        \n        a[''] = {\n            show = true,\n            changed = true\n        }\n        return true\n    end\n    \nend",
            "custom_type": "stateupdate",
            "debuffType": "HELPFUL",
            "events": "UNIT_SPELLCAST_SENT, UNIT_SPELLCAST_STOP:player, UNIT_SPELLCAST_CHANNEL_STOP:player, UNIT_SPELLCAST_START:player",
            "type": "custom",
            "unit": "player"
          },
          "untrigger": []
        },
        "3": {
          "trigger": {
            "check": "event",
            "custom": "function(allstates, event, ...)\n    \n    local unitTarget, spellName = ...\n    \n    if unitTarget ~= \"player\" then\n        return\n    end\n    \n    if event == \"UNIT_SPELLCAST_CHANNEL_STOP\" then\n        aura_env.startTime = nil\n        allstates[\"\"] = {\n            show = false,\n            changed = true,\n        }\n        aura_env.SetTicksCount(200, 0)\n        return true\n    end\n    \n    if event ~= \"UNIT_SPELLCAST_CHANNEL_START\" and event ~= \"UNIT_SPELLCAST_CHANNEL_UPDATE\" then\n        return\n    end\n    \n    local spellConfig = aura_env.spellConfig[spellName]\n    if not spellConfig then\n        return\n    end\n    \n    local baseTicks = spellConfig.ticks\n    local tickCount = baseTicks\n    \n    aura_env.SetTicksCount(100 / tickCount, 0)\n    \n    allstates[\"\"] = {\n        show = true,\n        changed = true,\n    }\n    \n    return true\nend",
            "custom_type": "stateupdate",
            "debuffType": "HELPFUL",
            "events": "UNIT_SPELLCAST_CHANNEL_START:player, UNIT_SPELLCAST_CHANNEL_STOP:player",
            "type": "custom",
            "unit": "player"
          },
          "untrigger": []
        },
        "activeTriggerMode": -10,
        "customTriggerLogic": "function(t)\n    return t[1]\nend",
